    shard.tick()?;

    let ticket = shard
        .pending_action_get(run)
        .ok_or("missing pending ticket")?;

    let journal_len_before = journal.len();

    let output = ActionOutputReady {
        output_slot: SlotIdx::ZERO,
        value: SlotValue::I64(42),
        taint: Taint::Clean,
        encoded_len: 2,
    };
    shard.enqueue(ShardCommand::ActionCompleted { ticket, output })?;
    shard.tick()?;

    let journal_len_after = journal.len();
    assert!(journal_len_after > journal_len_before, "journal should have grown");

    let events = journal.events();
    let step_succeeded = events.iter().find(|e| {
        matches!(e, ActualRuntimeJournalEvent::StepSucceeded { run: r, step, attempt } if *r == run && *step == StepIdx::ZERO && *attempt == 1)
    });
    assert!(step_succeeded.is_some(), "expected StepSucceeded event");

    Ok(())
}
